// ─── File: BlueGreenDemo.java ───
// Blue-green via weighted routing: gradual shift blue→green, instant rollback.
package com.bank.gateway.demo;

import java.util.logging.*;

public class BlueGreenDemo {
    private static final Logger log = Logger.getLogger("BlueGreen");
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setLevel(Level.ALL); h.setFormatter(new BgLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BlueGreenRouter router = new BlueGreenRouter(100, 0); // start: all BLUE
        AccountService service = new AccountService();
        DeploymentController deploy = new DeploymentController(router, service);

        log.info("=== Step 1: 100% BLUE ===");
        deploy.sendBatch(10);

        log.info("=== Step 2: 90% BLUE / 10% GREEN (canary weight) ===");
        router.setWeights(90, 10); deploy.sendBatch(10);

        log.info("=== Step 3: 50/50 ===");
        router.setWeights(50, 50); deploy.sendBatch(10);

        log.info("=== Step 4: 100% GREEN (full cutover) ===");
        router.setWeights(0, 100); deploy.sendBatch(10);

        log.info("=== Incident: GREEN starts failing → INSTANT rollback to BLUE ===");
        service.setGreenFailing(true);
        deploy.sendBatch(4);                // green errors visible
        router.setWeights(100, 0);          // rollback = weight change only
        log.info("Rolled back to 100% BLUE");
        service.setGreenFailing(false);
        deploy.sendBatch(4);                // healthy again
    }
}

// ─── Would be in routing/Backend.java ───
enum Backend { BLUE, GREEN }

// ─── Would be in routing/WeightedRoute.java ───
class WeightedRoute {
    volatile int blueWeight; volatile int greenWeight;
    WeightedRoute(int blue, int green) { this.blueWeight = blue; this.greenWeight = green; }
}

// ─── Would be in routing/BlueGreenRouter.java ───
class BlueGreenRouter {
    private static final Logger log = Logger.getLogger("BlueGreen");
    private final WeightedRoute route;
    private final java.util.Random rnd = new java.util.Random(7);
    BlueGreenRouter(int blue, int green) { this.route = new WeightedRoute(blue, green); }

    // Reconfigured at runtime — this is the entire "release" / "rollback" action.
    void setWeights(int blue, int green) {
        route.blueWeight = blue; route.greenWeight = green;
        log.info(() -> "weights set BLUE=" + blue + " GREEN=" + green);
    }

    // Pick a backend in proportion to the current weights.
    Backend pick() {
        int total = route.blueWeight + route.greenWeight;
        if (total == 0) return Backend.BLUE;
        int roll = rnd.nextInt(total);
        return roll < route.blueWeight ? Backend.BLUE : Backend.GREEN;
    }
}

// ─── Would be in service/AccountService.java ───
class AccountService {
    private volatile boolean greenFailing = false;
    void setGreenFailing(boolean f) { this.greenFailing = f; }
    // simulate serving from a specific color backend
    String serve(Backend backend, String accountId) {
        if (backend == Backend.GREEN && greenFailing) throw new RuntimeException("GREEN 500 error");
        return backend + " served " + accountId + " balance=Rs.1000000";
    }
}

// ─── Would be in deploy/DeploymentController.java ───
class DeploymentController {
    private static final Logger log = Logger.getLogger("BlueGreen");
    private final BlueGreenRouter router; private final AccountService service;
    DeploymentController(BlueGreenRouter router, AccountService service) {
        this.router = router; this.service = service;
    }
    void sendBatch(int n) {
        int blue = 0, green = 0, errors = 0;
        for (int i = 0; i < n; i++) {
            Backend b = router.pick();
            try { service.serve(b, "SAV2001"); if (b == Backend.BLUE) blue++; else green++; }
            catch (RuntimeException ex) { errors++; log.warning(() -> "error from " + b + ": " + ex.getMessage()); }
        }
        final int fb = blue, fg = green, fe = errors;
        log.info(() -> "batch result → BLUE=" + fb + " GREEN=" + fg + " errors=" + fe);
    }
}

// ─── Would be in BgLogFormatter.java ───
class BgLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
